import{_ as e,o as l,c as p,a2 as i}from"./chunks/framework.B95GhZQo.js";const u=JSON.parse('{"title":"子敬探索世界｜我决定公开挑战：通过创业赚到第 N 个 100 万","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/weekly/2026/2026-07-23.md","filePath":"knowledge/weekly/2026/2026-07-23.md","lastUpdated":1785058572000}'),o={name:"knowledge/weekly/2026/2026-07-23.md"};function t(n,a,s,r,d,c){return l(),p("div",null,[...a[0]||(a[0]=[i(`<h1 id="子敬探索世界-我决定公开挑战-通过创业赚到第-n-个-100-万" tabindex="-1">子敬探索世界｜我决定公开挑战：通过创业赚到第 N 个 100 万 <a class="header-anchor" href="#子敬探索世界-我决定公开挑战-通过创业赚到第-n-个-100-万" aria-label="Permalink to &quot;子敬探索世界｜我决定公开挑战：通过创业赚到第 N 个 100 万&quot;">​</a></h1><blockquote><p>状态：草稿</p></blockquote><blockquote><p>周期：2026-W30</p></blockquote><blockquote><p>这是长期挑战的总纲与第一篇正文，不是第一季项目记录。第一季的具体项目、100 万元统计口径和正式发布时间尚未确定。</p></blockquote><p>我准备做一件可能失败、但值得从今天开始记录的事：公开挑战通过创业赚到第 N 个 100 万。</p><p>我的个人 IP 叫做“子敬探索世界”。创业是这个母 IP 下面的一条长期栏目，栏目叫“子敬创业”，固定口号叫“从零单排”。“从零”是因为我从项目尚未确定、结果尚未发生的此刻开始记录；“单排”是因为所有内容都从我的第一视角出发，我会自己思考、做判断并承担结果。它不代表拒绝合作，也不意味着把朋友、伙伴或团队的贡献算成我的个人成绩。</p><p>先说最坦诚的部分：我现在还不知道具体要做什么项目，也不知道什么时候能够做到，甚至不能保证最后一定成功。</p><p>但我不想等到一切都想清楚、做成功以后，再回来讲一个经过包装的故事。我更想从现在开始，把自己怎样寻找项目、怎样判断、怎样行动、哪里做对了、哪里做错了，以及后来怎样修正，原原本本地记录下来。</p><p>这不是第一季项目的开始，而是整个挑战的总纲。第一季要等我选定一个具体项目后才正式开始。</p><p>我的设想是：长期挑战可以分成很多季。每一季只围绕一个具体项目，目标是通过这个项目挑战一个新的 100 万。项目可能成功，也可能失败、停止或转型；只有符合事先冻结口径的真实个人所得达到 100 万，计数才会增加。</p><h2 id="我为什么要公开做这件事" tabindex="-1">我为什么要公开做这件事 <a class="header-anchor" href="#我为什么要公开做这件事" aria-label="Permalink to &quot;我为什么要公开做这件事&quot;">​</a></h2><p>我相信，一个人最终能够取得什么结果，既取决于他的认知，也取决于他的执行力。</p><p>只有认知，没有行动，认知就无法被现实检验；只有行动，没有认知，可能只是不断重复低质量的努力。两者缺一不可。</p><p>对每一季来说，最重要的仍然是验证一件事：我能不能让认知与执行在一个真实项目中完成闭环，为客户创造价值，并靠这个项目挑战一个新的 100 万。公开记录、知识沉淀和粉丝交流会陪伴这个过程，但它们不能替代项目本身的经营结果。</p><p>这里还需要分清两个层级：选定项目是每一季开始前的一次性入口；项目选定以后，我每周不会重新走一遍抽象的创业流程，而是在当季同一个项目里推进具体行动、记录结果、形成自己的思考、公开进展，再把粉丝问题和建议带回下一周行动。</p><p>所以这个挑战不只记录“赚了多少钱”，还要留下完整的判断链：我为什么这样想、具体做了什么、现实给了什么反馈、我怎样总结，以及认知和行动怎样随之改变。</p><p>我现在的项目还没有确定。但寻找项目、判断机会、排除错误方向和做出第一次验证，本身就是创业过程的一部分。我不准备为了尽快开拍，假装自己已经找到了答案。</p><h2 id="我的第一性原理-坦诚" tabindex="-1">我的第一性原理：坦诚 <a class="header-anchor" href="#我的第一性原理-坦诚" aria-label="Permalink to &quot;我的第一性原理：坦诚&quot;">​</a></h2><p>这件事真正的底层，不是账号运营技巧，也不是设计一个看起来很厉害的人设，而是坦诚。</p><p>坦诚不是毫无边界地公开，也不是想到什么就说什么。坦诚是：不编造经历，不夸大结果，不隐藏失败，不把别人的贡献说成自己的，也不把尚未知道的事情包装成确定答案。</p><p>如果这一周没有进展，我会说没有进展；如果一个判断被现实证明是错的，我会保留原来的判断，再说明它为什么错、我是怎样修正的；如果项目失败了，失败也会成为记录的一部分。</p><p>我希望别人最终信任的，不是一个永远正确的人，而是一个愿意面对事实、承担结果、持续修正的人。</p><h2 id="认知必须经过执行" tabindex="-1">认知必须经过执行 <a class="header-anchor" href="#认知必须经过执行" aria-label="Permalink to &quot;认知必须经过执行&quot;">​</a></h2><p>我会把自己的思考整理成结构，但我不想让它停留在观点层面。</p><p>每一个重要判断，都应该尽可能进入真实行动：去访谈、去测试、去做产品、去接触客户、去承担成本，再用结果反过来检验判断。</p><p>这个过程可以概括成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>形成判断</span></span>
<span class="line"><span>→ 采取行动</span></span>
<span class="line"><span>→ 获得真实反馈</span></span>
<span class="line"><span>→ 修正认知</span></span>
<span class="line"><span>→ 再次行动</span></span></code></pre></div><p>认知让行动少走弯路，执行让认知不再自欺。真正有价值的，不是我说过什么，而是这些判断能不能在现实中产生结果。</p><h2 id="我希望和粉丝一起完成这个过程" tabindex="-1">我希望和粉丝一起完成这个过程 <a class="header-anchor" href="#我希望和粉丝一起完成这个过程" aria-label="Permalink to &quot;我希望和粉丝一起完成这个过程&quot;">​</a></h2><p>公开记录的另一个意义，是让外部意见真正进入我的思考。</p><p>我会认真看大家的评论、质疑和建议。以后每一期，我会从粉丝评论中选择最多 5 条真实且有代表性的评论；不足 5 条时就少选，不为了栏目完整而凑数。面对这些评论，我会独立思考、核验、回答并总结，再更新自己的认知和行动；能够被现实验证的部分，会带进下一周的项目实践，并在后续公开结果。</p><p>但共创不意味着盲目听从，也不意味着把判断责任交给粉丝。大家提供新的信息、角度和质疑，我负责核验、判断、行动，并为最终决定承担责任。</p><p>如果有人指出我的错误，我希望自己能够坦诚地改；如果建议经过验证并不成立，我也会说明事实和边界。</p><h2 id="为什么要把全过程沉淀下来" tabindex="-1">为什么要把全过程沉淀下来 <a class="header-anchor" href="#为什么要把全过程沉淀下来" aria-label="Permalink to &quot;为什么要把全过程沉淀下来&quot;">​</a></h2><p>每周的正文、图片和视频不会只是发完就结束。</p><p>我会同时维护两类知识：</p><ul><li><strong>全局认知</strong>：记录截至现在，我对创业这件事最完整的理解。认知变化时，直接更新原来的文字和结构图；</li><li><strong>每周快照</strong>：保留这一周发生了什么、当时怎样思考、为什么发生变化。连续的快照可以还原整个创业过程。</li></ul><p>所有内容都会有完整文字版本。图片负责把结构讲清楚，视频负责降低理解成本，文字负责保存完整事实、思考过程和认知变化。</p><p>这样做首先是为了帮助我自己复盘。即使最后没有赚到 100 万，这个过程也应该留下真实、可检查、可以继续学习的东西。</p><h2 id="粉丝关系和未来收益" tabindex="-1">粉丝关系和未来收益 <a class="header-anchor" href="#粉丝关系和未来收益" aria-label="Permalink to &quot;粉丝关系和未来收益&quot;">​</a></h2><p>我也希望在长期交流中，逐渐形成一个愿意互相讨论、彼此信任的群体。</p><p>这种关系不会因为一季项目结束就自动清零。第一季愿意留下的人，如果持续从真实行动、公开复盘和问题回答中获得价值，可能继续参与第二季、第三季。他们带来的信息、问题、经验和反馈，可能让下一季拥有更好的起点。这是我所理解的粉丝复利。</p><p>但真正复利的不是粉丝数量，而是持续提供价值后形成的自愿信任关系。它可能降低下一季的信息获取、需求验证和传播成本，却不能保证下一个项目成功，也不能替代新一季继续创造价值。</p><p>但粉丝不是我拥有的资源，建立群聊也不等于拥有价值。真正有价值的是：有人提出真实问题，有人提供不同经验，我愿意去验证和交付，参与的人也能从中得到帮助。</p><p>如果未来这个过程产生收益，它应该来自真实的产品、服务或项目，来自自愿、透明、能够退出的价值交换，而不是来自收割注意力或者利用信任。</p><p>这不是单方面从粉丝身上变现，而是在互利的基础上创造价值。如果价值没有成立，收益也不应该凭空成立。</p><h2 id="现在-我还没有答案" tabindex="-1">现在，我还没有答案 <a class="header-anchor" href="#现在-我还没有答案" aria-label="Permalink to &quot;现在，我还没有答案&quot;">​</a></h2><p>目前，我只确定了几件事：</p><ol><li>长期目标是通过一季又一季的创业，赚到第 N 个 100 万；</li><li>当前处于总纲和第一季项目选择阶段，具体项目还没有确定；</li><li>我会每周公开一次真实进展，不固定星期几；</li><li>底层思路是坦诚清晰、知行合一、开放独立、创造价值；</li><li>我会听取粉丝意见，独立思考并总结，再更新自己的认知和行动；</li><li>全过程会沉淀为文字、图片、视频、全局认知和每周快照。</li></ol><p>接下来，我要做的不是继续讨论宏大的道理，而是形成第一季项目选择标准，选定一个具体项目，并真正开始行动。</p><p>如果你愿意参与，我想先听两个问题：</p><ul><li>如果你是我，你会先验证什么创业问题？</li><li>你认为这套底层逻辑里，最容易自欺或者失败的地方是什么？</li></ul><p>我会把有代表性的问题带进下一次更新。</p><h2 id="本期知识记录" tabindex="-1">本期知识记录 <a class="header-anchor" href="#本期知识记录" aria-label="Permalink to &quot;本期知识记录&quot;">​</a></h2><ul><li>当前全局认知：<a href="./../../global/entrepreneurship-challenge-first-principles"><code>创业挑战的底层逻辑</code></a></li><li>本期新增：形成“多季母挑战—每季单项目周循环—能力知识与信任关系跨季复利”的总纲结构，并把“坦诚—认知—执行—共创修正—互利价值”明确为长期底层支点。</li><li>下一步验证：冻结 100 万元的统计口径；形成第一季项目选择标准；选定一个具体项目开展行动。</li><li>图片：<a href="../../../publishing/2026-07-23/cover.png"><code>长期挑战总纲图片评审稿</code></a></li><li>图片状态：总纲图已获用户认可</li><li>视频脚本：<code>publishing/2026-07-23/video-script.md</code>（内部生产稿，不在公开网站展示）</li><li>视频：最终提交版为 HyperFrames 58.518 秒竖屏视频 <code>publishing/2026-07-23/video-final-58s.mp4</code>；1080 × 1920，H.264 + AAC，30 fps</li><li>抖音发布：已于 2026-07-23 17:42 提交“子敬探索世界”账号，公开、立即发布，作者声明为“内容由 AI 生成”，平台快速检测显示“作品未见异常”，当前状态为“审核中”</li><li>抖音链接：平台审核完成后补充</li><li>发布记录：<code>publishing/2026-07-23/publish-record.md</code>（内部发布记录，不在公开网站展示）</li><li>公开知识页：<a href="https://zijing-explores-world.wuzhenyu-wzy.chatgpt.site/knowledge/weekly/2026/2026-07-23" target="_blank" rel="noreferrer"><code>子敬探索世界</code></a></li><li>网站验证：首版已构建并部署；当前页面由本地 Markdown 直接生成</li></ul><h2 id="后续修正" tabindex="-1">后续修正 <a class="header-anchor" href="#后续修正" aria-label="Permalink to &quot;后续修正&quot;">​</a></h2><blockquote><p>本文目前是草稿。冻结后不静默改写原判断；后续修正将在这里说明，并链接发生修正的日期正文。</p></blockquote>`,57)])])}const b=e(o,[["render",t]]);export{u as __pageData,b as default};
